<script setup>
import {computed,onMounted,ref} from 'vue';import {accountApi} from '../../api/accountApi.js';import {date} from '../../api/client.js';import {useAuth} from '../../stores/auth.js';import {useToast} from '../../stores/toast.js';import BookingTicket from '../../components/BookingTicket.vue';
const auth=useAuth(),toast=useToast(),statusTab=ref('all'),bookings=ref([]),ticket=ref(null);
const filteredBookings=computed(()=>bookings.value.filter(b=>statusTab.value==='all'||(statusTab.value==='paid'?b.status==='PAID':b.status==='PENDING_PAYMENT')));
async function load(){try{bookings.value=await accountApi.bookings()}catch(e){toast.show(e.message)}}function logout(){auth.logout();location.href='/'}onMounted(load);
</script>
<template><section class="section account-page figma-account"><aside class="account-menu"><h3>Tài khoản</h3><div class="profile-head"><span class="avatar large">{{auth.user.value?.fullName?.[0]}}</span><div><b>{{auth.user.value?.fullName}}</b><small>{{auth.user.value?.email}}</small></div></div><button class="active">▣ Lịch sử đặt vé</button><button @click="logout">↪ Đăng xuất</button></aside><main class="account-content"><h2>Lịch sử đặt vé</h2><div class="history-tabs"><button :class="{active:statusTab==='all'}" @click="statusTab='all'">Tất cả</button><button :class="{active:statusTab==='pending'}" @click="statusTab='pending'">Chờ thanh toán</button><button :class="{active:statusTab==='paid'}" @click="statusTab='paid'">Đã thanh toán</button></div><BookingTicket v-for="booking in filteredBookings" :key="booking.code" :booking="booking" @view="ticket=booking"/><div v-if="!filteredBookings.length" class="empty card">Chưa có vé trong mục này.</div></main><div v-if="ticket" class="modal ticket-modal" @click.self="ticket=null"><article class="electronic-ticket"><button class="modal-close" @click="ticket=null">×</button><h3>Vé điện tử</h3><div class="ticket-brand"><b>⚡ FastTravel</b><span>{{ticket.status}}</span></div><small>Mã đặt vé</small><h2>{{ticket.code}}</h2><div class="ticket-qr">▦<small>Mã vé</small></div><dl><div><dt>Họ và tên</dt><dd>{{ticket.tickets?.[0]?.passengerName||auth.user.value?.fullName}}</dd></div><div class="wide"><dt>Hành trình</dt><dd>{{ticket.trip.route}}</dd></div><div><dt>Thời gian</dt><dd>{{date(ticket.trip.departureTime)}}</dd></div><div><dt>Ghế</dt><dd>{{ticket.tickets?.map(t=>t.seat).join(', ')}}</dd></div></dl></article></div></section></template>
